command:
// ==========================================
// LUNAS WIRKUNG: GEISTERSCHRECKEN (ZERZAL)
//
// - Aura 16 Schritt, QS Stufen Furcht
// - Aura + Furchteffekte über Block 5
// - gekoppelte Effekte mit Link-ID + Cleanup
// - erneutes Wirken nutzt bestehende Aura/QS
// - eine Karte + roter GM-Button über Block 19.8
// - gespeicherte GM-Anfrage, kein neues Target
// ==========================================


// ============================================================
// === 1 - GLOBALER CLEANUP-HOOK ===============================
// ============================================================

if (globalThis._dskGeisterschreckenCleanupHookId) {
    Hooks.off("deleteActiveEffect", globalThis._dskGeisterschreckenCleanupHookId);
}

globalThis._dskGeisterschreckenCleanupHookId = Hooks.on("deleteActiveEffect", async effect => {
    if (effect.getFlag("dsk", "isGeisterschreckenAura") !== true) return;

    const aktiveGMs = game.users.filter(user => user.isGM && user.active)
        .sort((a, b) => String(a.id).localeCompare(String(b.id)));
    const zustaendigerGM = aktiveGMs[0] || null;

    if (zustaendigerGM && game.user.id !== zustaendigerGM.id) return;
    if (!zustaendigerGM && !game.user.isGM) return;

    const linkId = effect.getFlag("dsk", "geisterschreckenLinkId");
    const gespeicherteUuids = effect.getFlag("dsk", "linkedDebuffUuids") || [];
    const bereitsGeloescht = new Set();
    let entfernteEffekte = 0;

    for (const uuid of gespeicherteUuids) {
        if (!uuid) continue;

        try {
            const debuff = await fromUuid(uuid);
            if (!debuff || debuff.documentName !== "ActiveEffect") continue;
            if (linkId && debuff.getFlag("dsk", "geisterschreckenLinkId") !== linkId) continue;

            bereitsGeloescht.add(debuff.uuid);
            await debuff.delete({ dskGeisterschreckenAuraEnd: true });
            entfernteEffekte++;
        } catch (error) {
            console.warn("Geisterschrecken: Zieleffekt konnte nicht über seine UUID gelöscht werden.", { uuid, error });
        }
    }

    if (!linkId) {
        console.warn("Geisterschrecken: Haupteffekt besitzt keine geisterschreckenLinkId.");
        return;
    }

    const actorsZumPruefen = new Map();
    for (const token of canvas.tokens?.placeables || []) {
        if (token.actor) actorsZumPruefen.set(token.actor.uuid, token.actor);
    }
    for (const actor of game.actors) {
        if (actor) actorsZumPruefen.set(actor.uuid, actor);
    }

    for (const actor of actorsZumPruefen.values()) {
        const debuffs = actor.effects.filter(debuff =>
            debuff.getFlag("dsk", "isGeisterschreckenDebuff") === true &&
            debuff.getFlag("dsk", "geisterschreckenLinkId") === linkId &&
            !bereitsGeloescht.has(debuff.uuid)
        );

        for (const debuff of debuffs) {
            bereitsGeloescht.add(debuff.uuid);
            await debuff.delete({ dskGeisterschreckenAuraEnd: true });
            entfernteEffekte++;
        }
    }

    console.log(`Geisterschrecken: ${entfernteEffekte} verbundene Furchteffekte entfernt.`, { linkId });
});


// ============================================================
// === 2 - INIT-MODUS ==========================================
// ============================================================

if (typeof args !== "undefined" && args[0] === "WeckerAufruf") {
    globalThis._dskGeisterschreckenInit = true;
    console.log("Geisterschrecken: Cleanup wurde initialisiert.");
    return;
}


// ============================================================
// === 3 - NORMALE AUSFÜHRUNG =================================
// ============================================================

(async function () {
    const macroUuid = this?.uuid || null;

    // +++ 3.1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.Effekt?.CheckTarget ||
        !globalThis.DSK?.EffektEnde?.Register || !globalThis.DSK?.QS?.Ermitteln ||
        !globalThis.DSK?.Token?.Finde || !globalThis.DSK?.Geometrie?.Distanz ||
        !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.Effekt?.CheckTarget ||
        !DSK_FW?.EffektEnde?.Register || !DSK_FW?.QS?.Ermitteln ||
        !DSK_FW?.Token?.Finde || !DSK_FW?.Geometrie?.Distanz ||
        !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");

    // +++ 3.2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++

    const gabenName = "Geisterschrecken", vollerName = "Geisterschrecken (Zerzal)", ahne = "Zerzal";
    const flagKey = "pendingGeisterschreckenZerzal", reichweite = 16, endeKey = "geisterschreckenZerzal";
    const endeText = "Die furchteinflößende Aura verblasst. Die betroffenen Geister erholen sich.";

    DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

    // +++ 3.3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
    };

    const findeAura = actor => actor?.effects?.find(effect =>
        (effect.name || effect.label || "") === vollerName &&
        effect.getFlag("dsk", "isGeisterschreckenAura") === true
    ) || null;

    const findeGeister = casterToken => (canvas.tokens?.placeables || [])
        .filter(token =>
            token?.actor && token.id !== casterToken.id &&
            DSK_FW.Effekt.CheckTarget(token.actor, "geist") &&
            DSK_FW.Geometrie.Distanz(casterToken, token) <= reichweite
        )
        .sort((a, b) => String(a.name).localeCompare(String(b.name), "de"));

    const ermittleAktuelleFurcht = actor => {
        let furcht = 0;

        for (const effect of actor?.effects || []) {
            if (effect.disabled) continue;

            if (effect.statuses?.has("feared") && !(effect.changes || []).length) {
                furcht += Number(effect.getFlag("dsk", "value")) || 1;
            }

            for (const change of effect.changes || []) {
                if (change.key === "system.status.feared") furcht += Number(change.value) || 0;
            }
        }

        const selbstvertrauen = actor?.effects?.find(effect =>
            !effect.disabled &&
            String(effect.name || effect.label || "").toLowerCase().includes("selbstvertrauen")
        );

        if (selbstvertrauen) furcht -= Number(selbstvertrauen.getFlag("dsk", "qs")) || 1;
        return Math.max(0, furcht);
    };

    const findeAktiveAuraFuerGM = () => {
        if (!game.user.isGM) return null;

        const kontrollierterToken = canvas.tokens.controlled[0];
        if (kontrollierterToken?.actor) {
            const effekt = findeAura(kontrollierterToken.actor);
            if (effekt) return { actor: kontrollierterToken.actor, token: kontrollierterToken, effekt };
        }

        const auren = (canvas.tokens?.placeables || []).map(token => ({
            actor: token.actor, token, effekt: token.actor ? findeAura(token.actor) : null
        })).filter(eintrag => eintrag.actor && eintrag.effekt);

        if (auren.length === 1) return auren[0];

        if (auren.length > 1) {
            ui.notifications.warn("Luna sagt 🌙: Mehrere Geisterschrecken-Auren sind aktiv. Bitte wähle den richtigen Wirkenden aus.");
        }

        return null;
    };

    // +++ 3.4 - GM-AUSWAHL ++++++++++++++++++++++++++++++++++++

    const frageGeisterAuswahl = async ({ casterToken, auraEffekt, qs }) => {
        const geister = findeGeister(casterToken);
        const linkId = auraEffekt?.getFlag("dsk", "geisterschreckenLinkId") || null;

        const geisterHtml = geister.length ? geister.map(token => {
            const betroffen = Boolean(linkId && token.actor.effects.find(effect =>
                effect.getFlag("dsk", "isGeisterschreckenDebuff") === true &&
                effect.getFlag("dsk", "geisterschreckenLinkId") === linkId
            ));

            const distanz = Math.round(DSK_FW.Geometrie.Distanz(casterToken, token) * 10) / 10;

            return `<label style="display:flex;gap:7px;align-items:flex-start;margin-bottom:6px;padding:6px 8px;background:rgba(255,255,255,.35);border-radius:4px;cursor:pointer;">
                <input type="checkbox" name="geist" value="${token.id}" ${betroffen ? "" : "checked"} ${betroffen ? "disabled" : ""} style="margin-top:4px;">
                <span><b>${token.name}</b><br><span style="font-size:.82em;color:#555;">${distanz} Schritt${betroffen ? " · bereits betroffen" : ""}</span></span>
            </label>`;
        }).join("") : `<p style="margin:0;color:#555;font-style:italic;">Kein platzierter Geist innerhalb von ${reichweite} Schritt gefunden.</p>`;

        return foundry.applications.api.DialogV2.wait({
            window: { title: vollerName },
            position: { width: 430 },
            content: `<form><div style="font-family:'Signika',sans-serif;">
                ${DSK_FW.UI.Header(vollerName, DSK_FW.Symbol(ahne))}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="margin:0 0 7px;">Welche Geister werden von <b>Zerzals Aura</b> betroffen?</p>
                    <p style="font-size:.85em;color:#555;"><b>Reichweite:</b> ${reichweite} Schritt · <b>Furcht:</b> ${qs} Stufe(n)</p>
                    <div style="padding:8px;max-height:210px;overflow-y:auto;background:rgba(0,0,0,.04);border-radius:4px;">${geisterHtml}</div>
                    <hr>
                    <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;">
                        <label for="unbekannteGeister" style="font-weight:bold;">Unbekannte Geister:</label>
                        <input id="unbekannteGeister" type="number" name="unbekannteGeister" value="${geister.length ? 0 : 1}"
                            min="0" max="20" step="1" style="width:70px;text-align:center;">
                    </div>
                    <p style="margin:6px 0 0;font-size:.82em;color:#555;">Entferne den Haken bei immunen oder nicht betroffenen Geistern.</p>
                </div>
            </div></form>`,
            buttons: [
                {
                    action: "ok", label: "Geisterschrecken anwenden", icon: "fas fa-ghost", default: true,
                    callback: event => {
                        const form = event.target.closest("form"), formData = new FormData(form);
                        return {
                            tokenIds: Array.from(form.querySelectorAll('input[name="geist"]:checked'))
                                .filter(input => !input.disabled).map(input => input.value),
                            unbekannteGeister: Math.max(0, Math.min(20, Math.trunc(Number(formData.get("unbekannteGeister")) || 0)))
                        };
                    }
                },
                { action: "cancel", label: "Abbrechen", icon: "fas fa-times", callback: () => null }
            ],
            rejectClose: false
        });
    };

    // +++ 3.5 - FURCHTEFFEKT ÜBER BLOCK 5 +++++++++++++++++++++

    const legeFurchtAufGeist = async ({ geistToken, casterActor, casterName, auraEffekt, linkId, qs }) => {
        const geistActor = geistToken?.actor;
        if (!geistActor) return null;

        const vorhanden = geistActor.effects.find(effect =>
            effect.getFlag("dsk", "isGeisterschreckenDebuff") === true &&
            effect.getFlag("dsk", "geisterschreckenLinkId") === linkId
        );
        if (vorhanden) return vorhanden;

        const debuff = await DSK_FW.Effekt.Anwenden({
            name: `Geisterschrecken - Furcht - von ${casterName}`, ahne,
            beschreibung: `Die Aura von <b>${casterName}</b> erfüllt diesen Geist mit <b>${qs} Stufe(n) Furcht</b>.`,
            gabeZiel: "geist", qs,
            skills: ["system.status.feared"], key: "direkterSystemwert", formel: String(qs),
            statuses: ["feared"], ziel: geistActor,
            flags: { dsk: {
                value: qs, max: 8, qs, ahne, casterUuid: casterActor.uuid,
                sourceAuraEffectId: auraEffekt.id, sourceTargetTokenId: geistToken.id,
                geisterschreckenLinkId: linkId, isGeisterschreckenDebuff: true
            }}
        });

        if (!debuff) return null;

        const korrekterFurchtwert = (debuff.changes || []).some(change =>
            change.key === "system.status.feared" &&
            Number(change.mode) === 2 &&
            Number(change.value) === qs
        );

        const korrekt =
            debuff.getFlag("dsk", "isGeisterschreckenDebuff") === true &&
            debuff.getFlag("dsk", "geisterschreckenLinkId") === linkId &&
            debuff.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            Number(debuff.getFlag("dsk", "value")) === qs &&
            korrekterFurchtwert;

        if (!korrekt) {
            await debuff.delete({ dskGeisterschreckenEffectFailed: true }).catch(() => {});
            return null;
        }

        return debuff;
    };

    // +++ 3.6 - HAUPTAURA ÜBER BLOCK 5 ++++++++++++++++++++++++

    const erstelleAura = async ({ casterActor, casterName, qs, messageId }) => {
        const linkId = foundry.utils.randomID(), dauerMinuten = qs * 3;
        const beschreibung =
            `<b>Zerzal</b> erfüllt <b>${casterName}</b> mit einer furchteinflößenden Aura.` +
            `<br><br>Jeder von der Spielleitung bestimmte Geist im Umkreis von <b>${reichweite} Schritt</b> erhält ` +
            `<b>${qs} Stufe(n) Furcht</b>.`;

        const aura = await DSK_FW.Effekt.Anwenden({
            name: vollerName, ahne, beschreibung, gabeZiel: "erwachte", qs, changes: [], ziel: casterActor,
            duration: { seconds: dauerMinuten * 60, startTime: game.time.worldTime }, origin: casterActor.uuid,
            flags: { dsk: {
                qs, ahne, reichweite, casterUuid: casterActor.uuid, isGeisterschreckenAura: true,
                geisterschreckenLinkId: linkId, linkedDebuffUuids: [], messageId,
                wirkungsende: { sfName: endeKey, basisEffektName: vollerName, beschreibungFuerEnde: endeText }
            }}
        });

        if (!aura) return null;

        const korrekt =
            (aura.name || aura.label || "") === vollerName &&
            aura.getFlag("dsk", "isGeisterschreckenAura") === true &&
            aura.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            aura.getFlag("dsk", "geisterschreckenLinkId") === linkId &&
            Number(aura.getFlag("dsk", "qs")) === qs;

        if (!korrekt) {
            await aura.delete({ dskGeisterschreckenEffectFailed: true }).catch(() => {});
            return null;
        }

        return aura;
    };

    // +++ 3.7 - AURA ANWENDEN ODER ERWEITERN ++++++++++++++++++

    const anwenden = async ({ casterActor, casterToken, qsEingabe, messageId }) => {
        if (!casterActor || !casterToken || !messageId) return false;

        const casterName = DSK_FW.ResolveTokenName(casterActor);
        let aura = findeAura(casterActor);
        const erneut = Boolean(aura);
        const qs = erneut
            ? Math.max(1, Math.floor(Number(aura.getFlag("dsk", "qs")) || 1))
            : Math.max(1, Math.floor(Number(qsEingabe) || 1));

        const auswahl = await frageGeisterAuswahl({ casterToken, auraEffekt: aura, qs });
        if (auswahl === null) return false;

        if (!aura) aura = await erstelleAura({ casterActor, casterName, qs, messageId });

        if (!aura) {
            await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
                messageId, gabenName: vollerName, ahne,
                beschreibung: "Die furchteinflößende Aura konnte nicht angelegt werden.",
                wirkender: casterName, ziele: [],
                misserfolge: [{ name: casterName, grund: "Aura konnte nicht angelegt werden" }],
                dauerText: `${qs * 3} Minuten (QS ${qs})`, erfolgreich: false
            });
            ui.notifications.error(`Luna sagt 🌙: Die Aura konnte nicht auf ${casterName} angelegt werden!`);
            return true;
        }

        let linkId = aura.getFlag("dsk", "geisterschreckenLinkId");
        if (!linkId) {
            linkId = foundry.utils.randomID();
            await aura.update({
                "flags.dsk.geisterschreckenLinkId": linkId,
                "flags.dsk.linkedDebuffUuids": [],
                "flags.dsk.messageId": messageId
            });
        }

        const debuffUuids = new Set(aura.getFlag("dsk", "linkedDebuffUuids") || []);
        const erfolge = [], misserfolge = [];

        for (const tokenId of auswahl.tokenIds) {
            const geistToken = canvas.tokens.get(tokenId);
            const geistName = geistToken?.name || geistToken?.actor?.name || "Unbekannter Geist";

            if (!geistToken?.actor) {
                misserfolge.push({ name: geistName, grund: "Geist wurde nicht gefunden" });
                continue;
            }

            if (DSK_FW.Geometrie.Distanz(casterToken, geistToken) > reichweite) {
                misserfolge.push({ name: geistName, grund: "Außerhalb der Reichweite" });
                continue;
            }

            if (!DSK_FW.Effekt.CheckTarget(geistToken.actor, "geist")) {
                misserfolge.push({ name: geistName, grund: "Kein Geist" });
                continue;
            }

            const debuff = await legeFurchtAufGeist({
                geistToken, casterActor, casterName, auraEffekt: aura, linkId, qs
            });

            if (!debuff) {
                misserfolge.push({ name: geistName, grund: "Furchteffekt konnte nicht angelegt werden" });
                continue;
            }

            debuffUuids.add(debuff.uuid);
            await new Promise(resolve => setTimeout(resolve, 50));

            erfolge.push({
                name: `${geistName} – Gesamtfurcht ${ermittleAktuelleFurcht(geistToken.actor)}`,
                rolle: `Furcht +${qs}`
            });
        }

        if (auswahl.unbekannteGeister > 0) {
            erfolge.push({
                name: `Unbekannt (${auswahl.unbekannteGeister}) – Furcht ${qs}`,
                rolle: auswahl.unbekannteGeister === 1 ? "Unbekannter Geist" : "Unbekannte Geister"
            });
        }

        await aura.update({
            "flags.dsk.linkedDebuffUuids": Array.from(debuffUuids),
            "flags.dsk.messageId": messageId
        });

        const dauerMinuten = qs * 3;
        let dauerText = `${dauerMinuten} Minuten (QS ${qs})`;

        if (erneut) {
            const rest = Number(aura.duration?.remaining);
            if (Number.isFinite(rest)) {
                dauerText = `${Math.max(0, Math.ceil(rest / 60))} Minuten verbleibend (QS ${qs})`;
            }
        }

        const beschreibung =
            `<b>Zerzal</b> erfüllt <b>${casterName}</b> mit einer furchteinflößenden Aura.` +
            `<br><br>Jeder von der Spielleitung bestimmte Geist im Umkreis von <b>${reichweite} Schritt</b> erhält ` +
            `<b>${qs} Stufe(n) Furcht</b>.` +
            (auswahl.unbekannteGeister > 0
                ? `<br><br>Innerhalb der Aura befinden sich möglicherweise <b>${auswahl.unbekannteGeister}</b> ` +
                  `noch nicht platzierte, verborgene oder bislang unbekannte Geister.`
                : "");

        const erfolgreich = erfolge.length > 0;

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId, gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
            ziele: erfolge, misserfolge, dauerText, erfolgreich
        });

        if (erfolgreich) {
            ui.notifications.info(`Luna sagt 🌙: Geisterschrecken wurde auf ${erfolge.length} Eintrag/Einträge angewendet.`);
        } else {
            ui.notifications.warn("Luna sagt 🌙: Kein Geist wurde von Geisterschrecken betroffen.");
        }

        return true;
    };

    // +++ 3.8 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++

    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!casterActor || !daten || !game.user.isGM) return false;

        if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
            ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum wirkenden Akteur.");
            return false;
        }

        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
            return false;
        }

        const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);

        if (!casterToken) {
            ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`);
            return false;
        }

        return anwenden({
            casterActor, casterToken, qsEingabe: daten.qs, messageId: daten.messageId
        });
    };

    // +++ 3.9 - GM-MODUS ++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
                if (!daten) continue;

                if (await verarbeiteAnfrage(anfrageActor, daten)) {
                    await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
                }
            }
            return;
        }

        const aktiveAura = findeAktiveAuraFuerGM();

        if (aktiveAura) {
            let messageId = aktiveAura.effekt.getFlag("dsk", "messageId");

            if (!game.messages.get(messageId)) {
                const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
                    gabenName: vollerName, ahne,
                    beschreibung: "Die bestehende Aura wird auf weitere Geister angewendet.",
                    wirkender: DSK_FW.ResolveTokenName(aktiveAura.actor),
                    ziele: [], misserfolge: [], dauerText: "bestehende Restdauer",
                    gmBereich: false, anfragenderUserId: game.user.id
                });

                messageId = nachricht?.id || null;
                if (messageId) await aktiveAura.effekt.update({ "flags.dsk.messageId": messageId });
            }

            if (messageId) {
                await anwenden({
                    casterActor: aktiveAura.actor, casterToken: aktiveAura.token,
                    qsEingabe: aktiveAura.effekt.getFlag("dsk", "qs"), messageId
                });
            }
            return;
        }
    }

    // +++ 3.10 - WIRKENDER UND QS +++++++++++++++++++++++++++++

    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor)
                .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
            game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) ||
            null;
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Konnte den Token des Wirkenden nicht finden!");

    const casterName = DSK_FW.ResolveTokenName(casterActor);
    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor, gabenName,
        suchbegriffe: ["Geisterschrecken Probe", "Geisterschrecken"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0, protokollieren: true
    });

    if (qs <= 0) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName, ahne,
            beschreibung: "Die furchteinflößende Aura konnte nicht entfesselt werden.",
            wirkender: casterName, ziele: [],
            misserfolge: [{ name: casterName, grund: "Probe fehlgeschlagen" }],
            dauerText: "0 Minuten", gmBereich: false, angewendet: true, erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 3.11 - GEMEINSAME KARTE + ROTER GM-BUTTON ++++++++++

    const dauerMinuten = qs * 3;
    const beschreibung =
        `<b>Zerzal</b> erfüllt <b>${casterName}</b> mit einer furchteinflößenden Aura.` +
        `<br><br>Jeder von der Spielleitung bestimmte Geist im Umkreis von <b>${reichweite} Schritt</b> erhält ` +
        `<b>${qs} Stufe(n) Furcht</b>.`;

    const gmLink = DSK_FW.GabenUI.GMMakroButton(
        macroUuid, "Effekt anwenden", "Das Makro muss durch die Spielleitung ausgeführt werden."
    );

    const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
        ziele: [], misserfolge: [], dauerText: `${dauerMinuten} Minuten (QS ${qs})`,
        gmLink, gmBereich: !game.user.isGM, anfragenderUserId: game.user.id
    });

    if (!nachricht) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Die Geisterschrecken-Karte konnte nicht erstellt werden!");
    }

    // +++ 3.12 - ANFRAGEDATEN +++++++++++++++++++++++++++++++++

    const anfrageDaten = {
        casterUuid: casterActor.uuid, casterName,
        casterTokenId: casterToken.id,
        casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
        qs, sceneId: canvas.scene?.id || null,
        requestedByUserId: game.user.id, messageId: nachricht.id,
        macroUuid, erstellt: Date.now()
    };

    // +++ 3.13 - GM DIREKT ODER ANFRAGE SPEICHERN +++++++++++++

    if (game.user.isGM) {
        await verarbeiteAnfrage(casterActor, anfrageDaten);
        await raeumeQSAuf(casterActor);
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);

    // +++ 3.14 - QS AUFRÄUMEN ++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);
    ui.notifications.info("Luna sagt 🌙: Geisterschrecken wurde bei der Spielleitung beantragt.");

}).call(this);
